schema = protobuf.load([modulepath('protobuf'), '/tests/data/sensor_stream.proto']);
bytes = protobuf.encode(schema, 'Event', struct('started', struct('timestamp_ms', 1, 'mode', 'auto')))
event = protobuf.decode(schema, 'Event', bytes);
event.kind
event.started

schema = protobuf.load([modulepath('protobuf'), '/tests/data/sensor_stream.proto']);
records = struct('timestamp_ms', {1000, 1040, 1080}, 'status', {int32(0), int32(1), int32(2)});
bytes = protobuf.encode(schema, 'SensorSample', records, 'Delimited', true);
numel(bytes)
